let tracked cell_perm: Option<cell::PointsTo<T>>;
let tail =
    atomic_with_ghost!(&queue.tail => load();
    returning tail;
    ghost tail_token => {
        // If `head != tail`, then we proceed with the operation.
        // We check here, ghostily, in the `open_atomic_invariant` block if that's the case.
        // If so, we proceed with the `consume_start` transition
        // and obtain the cell permission.
        cell_perm = if self.head as u64 != tail {
            let tracked cp = queue.instance.borrow().consume_start(&tail_token, self.consumer.borrow_mut());
            Option::Some(cp)
        } else {
            Option::None
        };
    }
);

input.newString:
let tracked cell_perm: Option<cell::PointsTo<T>>;
let tail =
    atomic_with_ghost!(&queue.tail => load();
    returning tail;
    ghost tail_token => {
        // If `head != tail`, then we proceed with the operation.
        // We check here, ghostily, in the `open_atomic_invariant` block if that's the case.
        // If so, we proceed with the `consume_start` transition
        // and obtain the cell permission.
        cell_perm = if self.head as u64 != tail {
            let tracked (_, cp) = queue.instance.borrow().consume_start(&tail_token, self.consumer.borrow_mut());
            Option::Some(cp)
        } else {
            Option::None
        };
    }
);

